CREATE POLICY "Users can upload own attendance photos" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'attendance-photos' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "Users can view own attendance photos" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'attendance-photos' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "Users can delete own attendance photos" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'attendance-photos' AND (storage.foldername(name))[1] = auth.uid()::text);